import{_ as r,o,c as a,a2 as e}from"./chunks/framework.BZO4qERu.js";const p=JSON.parse('{"title":"工作区","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guides/container.md","filePath":"zh/guides/container.md","lastUpdated":1792323081000}'),s={name:"zh/guides/container.md"};function n(l,t,i,d,h,g){return o(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="工作区" tabindex="-1">工作区 <a class="header-anchor" href="#工作区" aria-label="Permalink to &quot;工作区&quot;">​</a></h1><p>每个 Bot 都有自己的<strong>工作区</strong>——一台属于它的电脑：真实的文件系统、能执行命令的终端、预装好的工具链，还可以开一块看得见的桌面。你交给 Bot 的文件、它产出的结果、它装的工具，都住在这里，跨会话保留。</p><h2 id="它能干什么" tabindex="-1">它能干什么 <a class="header-anchor" href="#它能干什么" aria-label="Permalink to &quot;它能干什么&quot;">​</a></h2><ul><li>存文件、改文件——你随时能在 <strong>文件</strong> 标签页里看</li><li>跑脚本、装包：预装 <strong>Node.js</strong> 和 <strong>Python</strong>（<code>pip</code>、<code>uv</code> 都在 PATH 上），不用先折腾解释器</li><li>挂后台任务</li><li>跨会话保留状态——昨天没做完的，今天接着做</li><li>可选地运行可视化桌面和有头浏览器</li></ul><h2 id="在客户端里的入口" tabindex="-1">在客户端里的入口 <a class="header-anchor" href="#在客户端里的入口" aria-label="Permalink to &quot;在客户端里的入口&quot;">​</a></h2><p>Bot 详情页里这几个标签页都对着工作区：</p><table tabindex="0"><thead><tr><th>标签页</th><th>内容</th></tr></thead><tbody><tr><td><strong>工作区</strong></td><td>工作区的状态与生命周期：创建、启动、停止；运行信息、快照、导入导出</td></tr><tr><td><strong>文件</strong></td><td>浏览和编辑工作区文件系统</td></tr><tr><td><strong>终端</strong></td><td>在工作区里打开交互 shell</td></tr><tr><td><strong>桌面</strong></td><td>可视化桌面：实时画面，接管 / 交还键鼠控制</td></tr><tr><td><strong>网络</strong></td><td>工作区网络状态</td></tr><tr><td><strong>应用</strong></td><td>装进这个工作区的 App——技能、依赖、连接器（见<a href="./supermarket.html">应用市场</a>）</td></tr></tbody></table><h2 id="生命周期" tabindex="-1">生命周期 <a class="header-anchor" href="#生命周期" aria-label="Permalink to &quot;生命周期&quot;">​</a></h2><p>在 <strong>工作区</strong> 标签页管理：</p><ul><li><strong>创建</strong>：按模板建一个新工作区，过程有进度展示。</li><li><strong>启动 / 停止</strong>：不用时停掉省资源，内容不丢。</li><li><strong>删除</strong>：删掉这个运行实例。</li></ul><p>终端、桌面等大多数能力都需要工作区<strong>正在运行</strong>；装应用、更新应用也一样。标签页里同时会显示运行状态、镜像和后台任务数等运行信息。</p><h2 id="可视化桌面" tabindex="-1">可视化桌面 <a class="header-anchor" href="#可视化桌面" aria-label="Permalink to &quot;可视化桌面&quot;">​</a></h2><p><strong>桌面</strong> 标签页用来启用和查看图形桌面。启用后，Bot 可以在工作区里跑<strong>有头浏览器</strong>，你在桌面面板里看到的和它操作的是同一块屏幕：</p><ul><li>实时观看它的每一步操作</li><li>随时<strong>接管</strong>键鼠——输密码、过验证码——再把控制权<strong>交还</strong></li><li>浏览器会话保留在工作区里，下次任务免登录</li></ul><p>工具层面的差别见 <a href="./browser-computer-use.html">Browser / Computer Use</a>。</p><h2 id="快照" tabindex="-1">快照 <a class="header-anchor" href="#快照" aria-label="Permalink to &quot;快照&quot;">​</a></h2><p><strong>创建快照</strong>记录工作区当前状态，适合在大改之前留一个回滚点；<strong>恢复</strong>按某个快照回退，不要的快照可删。</p><h2 id="导入导出" tabindex="-1">导入导出 <a class="header-anchor" href="#导入导出" aria-label="Permalink to &quot;导入导出&quot;">​</a></h2><ul><li><strong>导出数据</strong>：把工作区文件打包下载。</li><li><strong>导入数据</strong>：上传归档并解进工作区。</li><li><strong>重置</strong>：把数据目录恢复到干净状态——文件系统乱了、想从头开始时用。</li></ul><div class="tip custom-block"><p class="custom-block-title">自部署相关</p><p>工作区跑在哪种运行时（containerd、Docker、Apple container、受信本地目录），以及 GPU 等宿主设备怎么透传给工作区，属于服务端的部署配置，见 <a href="./../self-hosted/workspace-backends.html">Workspace 后端</a>。Memoh Cloud 用户不需要关心这些。</p></div>',20)])])}const u=r(s,[["render",n]]);export{p as __pageData,u as default};
